package com.primehr.security;
import com.primehr.integration.administrative.*;import org.springframework.security.access.AccessDeniedException;import org.springframework.stereotype.Component;
@Component public class EvidenceWorkflowPermissionGuard{
 public static final String ASSESSMENT="primehr.evidence-assessment",VALIDATION="primehr.evidence-validation",ACTION="primehr.evidence-action";private final AdministrativeAuthorizationClient client;public EvidenceWorkflowPermissionGuard(AdministrativeAuthorizationClient c){client=c;}
 public PermissionDataScope require(String feature,PrimeHrAction action,String token){if(!feature.equals(ASSESSMENT)&&!feature.equals(VALIDATION)&&!feature.equals(ACTION))throw new IllegalArgumentException("Unsupported evidence workflow feature");var p=client.resolve(feature,token);boolean allowed=p.administrator()||p.canAccess()&&switch(action){case ACCESS->true;case ADD->p.canAdd();case EDIT->p.canEdit();case ARCHIVE->p.canDelete();case SUBMIT->p.canSubmit();case APPROVE->p.canApprove();case FINALIZE->p.canFinalize();default->false;};if(!allowed)throw new AccessDeniedException("Evidence workflow permission is required");var scope=p.administrator()?PermissionDataScope.AGENCY_WIDE:p.dataScope();if(scope!=PermissionDataScope.ASSIGNED_RECORDS&&scope!=PermissionDataScope.AGENCY_WIDE)throw new AccessDeniedException("Evidence workflow requires Assigned Records or Agency Wide scope");return scope;}
}
